CREATE TABLE public.player_presence (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, last_seen timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.player_presence TO service_role;
ALTER TABLE public.player_presence ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.presence_heartbeat() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; INSERT INTO public.player_presence(user_id,last_seen) VALUES(auth.uid(),now()) ON CONFLICT(user_id) DO UPDATE SET last_seen=now(); END $$;
CREATE OR REPLACE FUNCTION public.can_watch_game(_game_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS (SELECT 1 FROM public.games g WHERE g.id=_game_id AND g.status IN ('active','finished') AND g.player_o IS NOT NULL AND auth.uid() NOT IN (g.player_x,g.player_o) AND NOT public.is_blocked(auth.uid(),g.player_x) AND NOT public.is_blocked(auth.uid(),g.player_o) AND EXISTS (SELECT 1 FROM public.friendships f WHERE f.status='accepted' AND ((f.requester_id=auth.uid() AND f.addressee_id IN(g.player_x,g.player_o)) OR (f.addressee_id=auth.uid() AND f.requester_id IN(g.player_x,g.player_o))))); $$;
CREATE OR REPLACE FUNCTION public.friend_activity() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('friendId',p.id,'online',coalesce(pr.last_seen > now()-interval '90 seconds',false),'games',coalesce((SELECT jsonb_agg(jsonb_build_object('id',g.id,'mode',g.mode)) FROM public.games g WHERE g.status='active' AND p.id IN(g.player_x,g.player_o) AND public.can_watch_game(g.id)),'[]'::jsonb))),'[]'::jsonb) FROM public.profiles p LEFT JOIN public.player_presence pr ON pr.user_id=p.id WHERE auth.uid() IS NOT NULL AND NOT public.is_blocked(auth.uid(),p.id) AND EXISTS(SELECT 1 FROM public.friendships f WHERE f.status='accepted' AND ((f.requester_id=auth.uid() AND f.addressee_id=p.id) OR (f.addressee_id=auth.uid() AND f.requester_id=p.id))); $$;
CREATE OR REPLACE FUNCTION public.watch_friend_game(_game_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$ DECLARE result jsonb; BEGIN IF NOT public.can_watch_game(_game_id) THEN RAISE EXCEPTION 'This game is not available to watch'; END IF; SELECT jsonb_build_object('id',g.id,'mode',g.mode,'state',g.state,'status',g.status,'winner',g.winner,'xName',x.username,'xCountry',x.country,'oName',o.username,'oCountry',o.country) INTO result FROM public.games g JOIN public.profiles x ON x.id=g.player_x JOIN public.profiles o ON o.id=g.player_o WHERE g.id=_game_id; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.presence_heartbeat(),public.can_watch_game(uuid),public.friend_activity(),public.watch_friend_game(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.presence_heartbeat(),public.can_watch_game(uuid),public.friend_activity(),public.watch_friend_game(uuid) TO authenticated,service_role;